MOD = 10**9 + 7

def count_sequences(N, K):
    def mod_inv(a, p):
        return pow(a, p-2, p)

    def nCr(n, r, p):
        if r > n:
            return 0
        num = factorial(n) % p
        den = (factorial(r) * factorial(n-r)) % p
        return num * mod_inv(den, p) % p

    dp = [[0] * (K + 1) for _ in range(N + 1)]
    dp[0][0] = 1

    for i in range(1, N + 1):
        for j in range(1, min(i, K) + 1):
            dp[i][j] = sum(dp[k][j-1] for k in range(1, i // j + 1)) % MOD

    result = 0
    for i in range(1, N + 1):
        result = (result + dp[i][K]) % MOD

    return result

